const files = $input.all().map((item) => item.json).filter((file) => file?.id && file?.name);
const deleteNow = files.filter((file) => file.name === 'tasker-offsite-check.txt' || file.name.startsWith('tasker-retention-test'));
const groups = new Map();
const pattern = /^(tasker-(\d{8})T(\d{6})Z\.dump\.enc)(?:\.sha256)?$/;
for (const file of files) {
  const match = file.name.match(pattern);
  if (!match) continue;
  const key = match[1];
  const date = new Date(match[2].slice(0,4) + '-' + match[2].slice(4,6) + '-' + match[2].slice(6,8) + 'T' + match[3].slice(0,2) + ':' + match[3].slice(2,4) + ':' + match[3].slice(4,6) + 'Z');
  if (!groups.has(key)) groups.set(key, { key, date, files: [] });
  groups.get(key).files.push(file);
}
const snapshots = [...groups.values()].sort((a, b) => b.date - a.date);
const keep = new Set(snapshots.slice(0, 14).map((snapshot) => snapshot.key));
const weeklyKeys = new Set();
for (const snapshot of snapshots.slice(14)) {
  const monday = new Date(Date.UTC(snapshot.date.getUTCFullYear(), snapshot.date.getUTCMonth(), snapshot.date.getUTCDate()));
  const weekday = monday.getUTCDay() || 7;
  monday.setUTCDate(monday.getUTCDate() - weekday + 1);
  const weekKey = monday.toISOString().slice(0, 10);
  if (!weeklyKeys.has(weekKey) && weeklyKeys.size < 8) {
    weeklyKeys.add(weekKey);
    keep.add(snapshot.key);
  }
}
for (const snapshot of snapshots) {
  if (!keep.has(snapshot.key)) deleteNow.push(...snapshot.files);
}
return deleteNow.map((file) => ({ json: { id: file.id, name: file.name, retentionPolicy: '14 daily + 8 weekly' } }));
